    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 betLimit, uint256 value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (value)); require(value <= 1000000000000000000000000000000);
        require(address(this).balance >= value);
        require(betLimit != 0);

        c.AdjustBetAmounts(betLimit); if (__ESBMC_reverted()) return;

        uint256 limit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        bool wasPlayerBefore = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
        require(!wasPlayerBefore);

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.wager{value: value}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool isPlayerAfter = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted ? !isPlayerAfter : (isPlayerAfter && value == limit));
    }

    receive() external payable {}
}

