    }

    function _run(uint256 betLimit, uint256 value) internal {
        value = bound(value, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        vm.assume(betLimit != 0);
        try c.AdjustBetAmounts(betLimit) {} catch { return; }
        uint256 limit;
        try c.currentBetLimit() returns (uint256 __r) { limit = __r; } catch { return; }
        bool wasPlayerBefore;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { wasPlayerBefore = __r; } catch { return; }
        vm.assume(!wasPlayerBefore);
        try c.OpenToThePublic() {} catch { return; }
        bool reverted;
        try c.wager{value: value}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool isPlayerAfter;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { isPlayerAfter = __r; } catch { return; }
        assertTrue(reverted ? !isPlayerAfter : (isPlayerAfter && value == limit));
